import React, { useState, useEffect } from 'react';
import { useNavigate } from "react-router-dom"; // ✅ Import useNavigate

const Gallery = () => {
    const navigate = useNavigate(); // ✅ Initialize navigation

    const [products, setProducts] = useState([]);
    const [error, setError] = useState("");
    const [currentPage, setCurrentPage] = useState(1);
    const productsPerPage = 6;
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetch('http://localhost:5000/api/products')
            .then(response => response.json())
            .then(data => {
                console.log("Fetched data:", data);
                const productArray = Array.isArray(data) ? data : data.products || [];
                setProducts(productArray);
                setLoading(false);
            })
            .catch(error => {
                console.error("Error fetching products:", error);
                setError("Failed to load products.");
                setLoading(false);
            });
    }, []);

    const handleOrderClick = (product) => {
        navigate(`/customers/order/${product.id}`); // ✅ Navigate to order form with product id
    };

    if (loading) return <p>Loading...</p>;
    if (error) return <p>{error}</p>;

    // Pagination logic
    const indexOfLast = currentPage * productsPerPage;
    const indexOfFirst = indexOfLast - productsPerPage;
    const currentProducts = products.slice(indexOfFirst, indexOfLast);
    const totalPages = Math.ceil(products.length / productsPerPage);

    const handlePrevPage = () => {
        if (currentPage > 1) {
            setCurrentPage(prev => prev - 1);
        }
    };

    const handleNextPage = () => {
        if (currentPage < totalPages) {
            setCurrentPage(prev => prev + 1);
        }
    };

    return (
        <div className="gallery">
            <h1>Gallery</h1>
            <p>Kindly go through the pictures of our carpets and canopy brands.</p>

            <div className="gallery-grid">
                {currentProducts.length === 0 ? (
                    <p>No products found.</p>
                ) : (
                    currentProducts.map(product => (
                        <div key={product.id} className="gallery-item">
                            <img src={`http://localhost:5000${product.image_url}`} alt={product.name} />
                            <div className="item-info">
                                <h2>{product.name}</h2>
                                <p>{product.description}</p>
                                <p>{product.price}</p>
                                <button
                                    className="mt-2 px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
                                    onClick={() => handleOrderClick(product)} // ✅ Button triggers navigation
                                >
                                    Order Now
                                </button>
                            </div>
                        </div>
                    ))
                )}
            </div>

            {/* Pagination Controls */}
            <div className="pagination">
                <button onClick={handlePrevPage} disabled={currentPage === 1}>
                    Previous
                </button>
                <span>Page {currentPage} of {totalPages}</span>
                <button onClick={handleNextPage} disabled={currentPage === totalPages}>
                    Next
                </button>
            </div>
        </div>
    );
};

export default Gallery;
